import React from 'react';
import './Speakers.css';

const speakers = [
    {
        name: "Dr. Attiya Inayatullah",
        role: "Keynote Speaker",
        bio: "Dr. Attiya Inayatullah is a prominent Pakistani figure with a distinguished career in population welfare, human rights, and women's issues. She holds a PhD in Demographics and led the Family Planning Association of Pakistan for many years. She gained international recognition through her work with UNESCO and has been awarded the highest civilian award in Pakistan."
    },
    {
        name: "Ms. Naveen Balkhi",
        role: "CHRO & Director of Global Talent Management",
        bio: "Naveen Balkhi, a CHRO and Director of Global Talent Management at BSG Advisory, is recognized for her leadership in HR, strategy, and diversity. She provides expertise through keynote speeches and leadership development, focusing on global talent excellence."
    },
    {
        name: "Ms. Tina Hameed",
        role: "Founding Director, TLC at Atchison College",
        bio: "Tina Hameed is the Founding Director of the Teaching and Learning Centre (TLC) at Atchison College with 37 years of experience. She holds an M.Ed. from the University of Exeter and is an accredited tutor from the University of Bradford."
    },
    {
        name: "Dr. Tayyabah Amer Malik",
        role: "Experienced Academic Leader",
        bio: "Dr. Tayyabah Amer Malik is an experienced academic leader with a demonstrated history in education management. Skilled in coaching, curriculum development, and education planning, she holds a Masters Degree in Advance Professional Studies from University of Strathclyde."
    },
    {
        name: "Ms. Shireen Naqvi",
        role: "Workshop Facilitator & Coach",
        bio: "Shireen Naqvi is a highly respected figure known for her credibility in diversity and inclusion. A workshop facilitator and coach, she has worked with over 300 organizations and founded the School of Leadership."
    },
    {
        name: "Mr. Abbas Husain",
        role: "Corporate & Educational Policy Trainer",
        bio: "With over 30 years of experience, Abbas Husain is a seasoned corporate and educational policy trainer. He is renowned internationally for his teacher training workshops across multiple countries."
    }
];

const Speakers = () => {
    return (
        <section id="speakers" className="speakers-section">
            <div className="speakers-container">
                <div className="speakers-header">
                    <h2>Accomplished Thought Leaders</h2>
                    <p>Opportunity to engage with some of the country's most accomplished educators and take back skills to your classrooms and institutions.</p>
                </div>
                <div className="speakers-grid">
                    {speakers.map((speaker, index) => (
                        <div className="speaker-card" key={index}>
                            <div className="speaker-image-container">
                                <div className="speaker-placeholder">
                                    <svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1" strokeLinecap="round" strokeLinejoin="round">
                                        <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
                                        <circle cx="12" cy="7" r="4"></circle>
                                    </svg>
                                </div>
                                {/* Image will be added here later */}
                            </div>
                            <div className="speaker-info">
                                <span className="speaker-role">{speaker.role}</span>
                                <h3>{speaker.name}</h3>
                                <p className="speaker-bio">{speaker.bio}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default Speakers;
